{
  "packet_id": "H6-T02-3",
  "claim_id": "C041",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C041.component",
    "value": "The mapping reports a slow-export rate of approximately five percent.",
    "scope": "Reported rate used in the test-duration limitation, not a newly obtained experimental estimate.",
    "provenance": {
      "refs": [
        {
          "source_id": "P033",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P033 explicitly supplies the approximate reported rate and its relevance to short tests."
    }
  },
  "signal_basis": {
    "component_id": "C041.signal_basis",
    "value": "The mapping takes the approximate five-percent rate as reported background and proposes tracking the fraction of exports exceeding one hour; it does not present that measurement as already obtained.",
    "scope": "Background frequency and proposed slow-export measurement, without asserting that the perturbation establishes a five-percent rate.",
    "provenance": {
      "refs": [
        {
          "source_id": "P033",
          "role": "SUPPORT"
        },
        {
          "source_id": "P021",
          "role": "SUPPORT"
        },
        {
          "source_id": "P025",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans distinguish the reported background rate from the proposed measurements."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C041.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "This bounded reporting claim requires no unresolved empirical relation."
    }
  },
  "rationale": "The frozen claim concerns what rate is reported, not what the experimental response estimates. The mapping explicitly reports approximately five percent, consistent with the supplied one-in-twenty background. The operation need not independently establish that rate for this narrowly scoped claim to hold.",
  "uncertainty": "The reported rate's sampling precision and continued applicability are not established; neither is asserted by this claim.",
  "anomalies": []
}
